from typing import Dict, Iterable, List, Mapping

from .parse_movement_line import parse_movement_line
from .on_hand_by_location import on_hand_by_location


def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    """
    List SKUs whose stock has not moved out for a long time (dead stock).

    A SKU is dead stock when its total on-hand is positive and its most recent
    shipment (SHP) is at least `idle_days` days old. If a SKU has never shipped,
    use its earliest movement day instead. Movements dated after `today` are ignored.
    """
    if idle_days < 1:
        raise ValueError("idle_days must be >= 1")

    last_ship_day: Dict[str, int] = {}
    earliest_day: Dict[str, int] = {}
    valid_lines: List[str] = []

    for line in lines:
        s = line.strip()
        if not s or s.startswith('#'):
            continue
        p = parse_movement_line(line, case_sizes)
        if p['day'] > today:
            continue
        sku, day, mtype = p['sku'], p['day'], p['type']
        valid_lines.append(line)
        if sku not in earliest_day or day < earliest_day[sku]:
            earliest_day[sku] = day
        if mtype == 'SHP' and (sku not in last_ship_day or day > last_ship_day[sku]):
            last_ship_day[sku] = day

    on_hand = on_hand_by_location(valid_lines, case_sizes, as_of_day=today)
    sku_total: Dict[str, int] = {}
    for (sku, loc), qty in on_hand.items():
        sku_total[sku] = sku_total.get(sku, 0) + qty

    result: List[str] = []
    for sku, total in sku_total.items():
        if total <= 0:
            continue
        ref_day = last_ship_day.get(sku, earliest_day.get(sku, today))
        if today - ref_day >= idle_days:
            result.append(sku)
    return sorted(result)
