from typing import Any, Dict, Mapping

def normalize_sku(sku: str) -> str:
    return sku.strip().upper()

def parse_location(loc: str) -> str:
    # Basic canonicalization based on the example B-07-14-3
    return loc.strip().upper()

def parse_quantity(qty_str: str, case_size: int) -> int:
    # Expected format: "5 CS" or "7 EA"
    parts = qty_str.strip().split()
    if not parts:
        raise ValueError("Empty quantity")

    val = int(parts[0])
    unit = parts[1].upper() if len(parts) > 1 else "EA"

    if unit == "CS":
        return val * case_size
    elif unit == "EA":
        return val
    else:
        raise ValueError(f"Unknown unit {unit}")

def parse_movement_line(line: str, case_sizes: Mapping[str, int]) -> Dict[str, Any]:
    fields = [f.strip() for f in line.split(';')]
    if len(fields) != 5:
        raise ValueError("Wrong number of fields")

    day_str, type_str, sku_raw, loc_raw, qty_raw = fields

    try:
        day = int(day_str)
        if day < 0: raise ValueError()
    except ValueError:
        raise ValueError("Bad day")

    m_type = type_str.upper()
    if m_type not in ('RCV', 'SHP', 'RTN', 'ADJ'):
        raise ValueError("Unknown type")

    sku = normalize_sku(sku_raw)
    location = parse_location(loc_raw)

    case_size = case_sizes.get(sku, 1)
    qty = parse_quantity(qty_raw, case_size)

    if m_type == 'SHP':
        qty = -abs(qty)
    elif m_type in ('RCV', 'RTN'):
        qty = abs(qty)

    return {"day": day, "type": m_type, "sku": sku, "location": location, "qty": qty}
"
    }
  }
}
