from typing import Iterable, Mapping
from stockflow.parse_movement_line import parse_movement_line
import math

def average_daily_demand(lines: Iterable[str], case_sizes: Mapping[str, int], sku: str, start_day: int, end_day: int) -> int:
    """
    Computes the average daily demand for a given SKU over a specified day range.
    Demand is defined as the total quantity shipped (SHP) divided by the number of days in the range.
    The result should be rounded up to the nearest integer.
