from typing import Dict, List, Sequence, Tuple
from stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")

    merged_weights: Dict[str, int] = {}
    merged_qtys: Dict[str, int] = {}

    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("qty and unit weight must be > 0")
        if sku in merged_weights and merged_weights[sku] != weight:
            raise ValueError(f"SKU {sku} has inconsistent unit weights")
        merged_weights[sku] = weight
        if weight > max_parcel_grams:
            raise ValueError(f"Unit weight of {sku} exceeds max_parcel_grams")
        merged_qtys[sku] = merged_qtys.get(sku, 0) + qty

    # To keep lines together, we treat each SKU's total quantity as a single item if it fits.
    # If it doesn't fit, we split it into the largest possible chunks that do fit.
    items = []
    for sku, qty in merged_qtys.items():
        weight = merged_weights[sku]
        total_weight = qty * weight
        if total_weight <= max_parcel_grams:
            # Treat the whole line as one item for first_fit_decreasing
            # We store the quantity in the 'weight' slot temporarily or use a wrapper
            # But first_fit_decreasing expects (item, weight). 
            # Let's use a tuple (sku, qty) as the item and total_weight as the weight.
            items.append(((sku, qty), total_weight))
        else:
            # Split into chunks of max possible size
            remaining_qty = qty
            while remaining_qty > 0:
                chunk_qty = min(remaining_qty, max_parcel_grams // weight)
                items.append(((sku, chunk_qty), chunk_qty * weight))
                remaining_qty -= chunk_qty

    bins = first_fit_decreasing(items, max_parcel_grams)

    parcels = []
    for bin_items in bins:
        parcel = {}
        for (sku, qty), weight in bin_items:
            parcel[sku] = parcel.get(sku, 0) + qty
        parcels.append(parcel)

    return parcels
"}}}
